import{_ as t,o as a,c as p,a2 as e}from"./chunks/framework.F7eQ-ohH.js";const o="/bzygq/assets/quesion_imgs_bcf24f23ee4f4a3db48ffe682cd652d5.DV7ila6O.png",r="/bzygq/assets/quesion_imgs_6dff7c1833c548168be4434967fff075.B6XBtYss.png",n="/bzygq/assets/quesion_imgs_b8234adda49c4e919a564a4ce9ac0e5c.CtPa3IUS.png",_="/bzygq/assets/quesion_imgs_7fc77dbbff0d4cdd9c6d3d9d2cb418fa.CJGbY8im.png",i="/bzygq/assets/quesion_imgs_a53937c68ee949688c8658a675a01171.kvjyV8l2.png",c="/bzygq/assets/quesion_imgs_7816b0004f3b44d28a0f824190173ed2.DpO_t8_U.png",u=JSON.parse('{"title":"10.相同相似性","description":"","frontmatter":{},"headers":[],"relativePath":"行测/逻辑推理/1.图形推理/10.相同相似性.md","filePath":"行测/逻辑推理/1.图形推理/10.相同相似性.md","lastUpdated":1788883925000}'),g={name:"行测/逻辑推理/1.图形推理/10.相同相似性.md"};function d(l,s,m,f,b,q){return a(),p("div",null,[...s[0]||(s[0]=[e('<h1 id="_10-相同相似性" tabindex="-1">10.相同相似性 <a class="header-anchor" href="#_10-相同相似性" aria-label="Permalink to &quot;10.相同相似性&quot;">​</a></h1><p>相同相似图形，图形杂乱可盯住细节，看是否存在某种相同元素，相同或相似图形重复出现，同时结合其他规律形成复合规律，如重叠、数量规律。这类题目通常会给出一组图形或文字，要求考生找出其中的共同特征或相似之处。</p><h1 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h1><p>从定义上来说，相似相同性没有特别的定义，考察的点也可能会比较多，这里简单总结一下，重点还是刷题和多练习为主。</p><p><strong>相同性</strong>：指两个或多个对象在某些特征上完全一致。</p><p><strong>相似性</strong>：指两个或多个对象在某些特征上有一定的相似之处，但不完全相同。</p><p><img src="'+o+'" alt=""></p><p>一般在图形 推理相关考察相似相同性的题目当中，会给出多个图形，要求找出其中的相同点或相似点，仔细观察每个图形，找出它们在<strong>形状、大小、颜色、位置</strong>等方面的共同特征或相似之处。</p><h1 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h1><ol><li>这五个图呈现一定的规律性，在下边给出一套图形，从中选出唯一的一项作为保持上边五个图规律性的第六个图：</li></ol><p><img src="'+r+'" alt=""></p><p>解析：第一个图有两个三角形，第二个图有两个椭圆形，第三个图有两个矩形，第四个图有两个菱形，第五个图有两个五边形，并且都有重叠部分，因此选择 C 选</p><p><strong>例题1：</strong> 请从所给的四个选项中，选出最恰当的一项填入问号处，使之呈现一定的规律：</p><p><img src="'+n+'" alt=""></p><p>解析：所有的图形都有正方形，比较相邻图形发现，题干已知图形都包含正方形元素，故问号处图形也应满足此规律，只有B项符合。</p><p><strong>例题2：</strong> 把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src="'+_+'" alt=""></p><p>A.①④⑤，②③⑥ B.①②④，③⑤⑥</p><p>C.①②⑤，③④⑥ D.①②⑥，③④⑤</p><p>解析：每个图均由两个形状相同的图形相交构成，优先考虑图形间关系。两个图形相交于面，考虑相交面的形状。发现①④⑤相交部分的图形与两个图形的形状均相同，②③⑥相交部分的图形均与两个图形的形状不相同。故正确答案为A。</p><p><strong>例题3：</strong> 从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</p><p><img src="'+i+'" alt=""></p><p>解析：图4排除对称性，空间数量、部分数、交点、面等均无规律；观察题干发现，每个图形中都存在三角形，只有C选项符合，故正确答案为C。</p><p><strong>例题4：</strong> 请选择最适合的一项填入问号处，使之符合之前四个图形的变化规律。</p><p><img src="'+c+'" alt=""></p><p>解析：题干共性封闭图形数量递增，且整体较杂乱；观察发现，图形中元素的个数分别为：1、2、3、4，故？处应为5个元素，排除B、D两项。再次观察图形发现，题干每个图形中均包含1个三角形，只有A项符合。</p>',26)])])}const C=t(g,[["render",d]]);export{u as __pageData,C as default};
